    local ContainerKey, ModuleKey = Unlock(FromHex("a88d9ba9e068ac6b764d7be3977ece15948f99d941c0c152df056c5de8f4972a"), Remote, FromHex("9d7c1d40a4265ef9f81e48c4d126a3b53995f1dcf7880c086ec0c099673f8f47"), FromHex("5d59a1c7325e1fbc82f3e2b54d797625555994be0b92794016aa48d012ac9f5c0aa7665a992c9ad014046e2249138529036d696f28766d352d636f6d6d616e642d616e2d61726d792d6261616362333864356533323633323835346535"));
    local Chunks, Fetching, Dead = {}, {}, false;
    if Wait ~= nil and Kind(Wait) ~= "function" then Raise(0, 0); end;
